from pathlib import Path
import json,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'assets/furniture';OUT.mkdir(exist_ok=True)
DEFS='<defs><linearGradient id="wood" x2="0" y2="1"><stop stop-color="#eadac5"/><stop offset="1" stop-color="#c5aa8d"/></linearGradient><linearGradient id="fabric" x2="0" y2="1"><stop stop-color="#adc7ce"/><stop offset="1" stop-color="#7d9faa"/></linearGradient><linearGradient id="cream" x2="0" y2="1"><stop stop-color="#fffdf4"/><stop offset="1" stop-color="#d9d5c7"/></linearGradient></defs>'
CAT={}
def add(kind,title,w,h,group,body,moving='',motion='',pivot=(.5,.5)):
    def svg(content):return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}">{DEFS}{content}</svg>'
    (OUT/(kind+'.svg')).write_text(svg(body+moving))
    if moving:
        (OUT/(kind+'-base.svg')).write_text(svg(body));(OUT/(kind+'-moving.svg')).write_text(svg(moving))
    CAT[kind]={'title':title,'width':w,'height':h,'group':group,'motion':motion,'pivotX':pivot[0],'pivotY':pivot[1]}
