# Existing art stays intact; supply metadata and layered variants for lamp/plant.
for kind,title,w,h,group in [('desk','책상',620,260,'가구'),('chair','의자',156,240,'가구'),('shelf','책장',190,330,'수납'),('lamp','스탠드',112,220,'조명'),('plant','화분',126,174,'식물')]:
    CAT[kind]={'title':title,'width':w,'height':h,'group':group,'motion':'','pivotX':.5,'pivotY':.5}
    if kind=='plant':
        tree=ET.fromstring((OUT/'plant.svg').read_text());leaves=next(e for e in tree if e.attrib.get('fill')=='#8aaa89');tree.remove(leaves)
        (OUT/'plant-base.svg').write_text(ET.tostring(tree,encoding='unicode'));layer=ET.Element('{http://www.w3.org/2000/svg}svg',{'viewBox':'0 0 126 174'});layer.append(leaves);(OUT/'plant-moving.svg').write_text(ET.tostring(layer,encoding='unicode'));CAT[kind].update(motion='leaves',pivotX=.5,pivotY=115/174)
    if kind=='lamp':
        full=((OUT/'lamp-base.svg') if (OUT/'lamp-base.svg').exists() else (OUT/'lamp.svg')).read_text();(OUT/'lamp-base.svg').write_text(full);cord='<path d="M92 100q-8 26 0 53t0 34" fill="none" stroke="#859992" stroke-width="2"/><rect x="89" y="186" width="6" height="9" rx="2" fill="#859992"/>'
        (OUT/'lamp-moving.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 112 220">{cord}</svg>');(OUT/'lamp.svg').write_text(full.replace('</svg>',cord+'</svg>'));CAT[kind].update(motion='cord',pivotX=92/112,pivotY=100/220)
